import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address fuzzedCaddress, address[] memory _tos, uint v) public {
        // Admissible domain: _tos non-empty (enforced by c), and fuzzedCaddress different from address(c) to avoid self-call re-entrancy edge.
        vm.assume(_tos.length > 0);
        vm.assume(fuzzedCaddress != address(c));
        // The fuzzed caddress is an EOA; low-level call to it always succeeds, which triggers the bug.
        // Deploy no adversarial helper because the bug manifests on success, and EOA call succeeds.
        bool ok;
        // Observe c's behavior via try/catch to capture revert booleans.
        try c.transfer(from, fuzzedCaddress, _tos, v) returns (bool ret) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference always returns true (ok == true) because all EOA calls succeed and require(_s) passes.
        // Bug version reverts (ok == false) because it uses require(!_s) and _s is true on EOA success.
        assertTrue(ok);
    }
}

