pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address[] memory _tos, uint v) public {
        // 1. Restrict to admissible domain: non-empty array, reasonable length to avoid gas exhaustion
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 10);
        // Ensure from is not the zero address (common ERC20 restriction)
        vm.assume(from != address(0));

        // 2. Deploy an adversarial helper: a contract that always succeeds on transferFrom calls
        AlwaysSucceeder helper = new AlwaysSucceeder();
        address caddress = address(helper);

        // Drive the call through the reference contract C
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            success = result;
        } catch {
            success = false;
        }

        // 3. Assertion: For the reference contract, the transfer should always succeed (return true)
        assertTrue(success);
    }
}

contract AlwaysSucceeder {
    // This contract implements transferFrom to always succeed
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

